import http from 'node:http';import {fahrenheit} from './convert.mjs';import {available} from './stock.mjs';import {shipping} from './shipping.mjs';
export const handle=b=>({fahrenheit:fahrenheit(b.celsius),available:available(b.total,b.reserved),shipping:shipping(b.subtotal,b.delivery)});
export const createApp=()=>http.createServer(async(req,res)=>{try{let s='';for await(const c of req)s+=c;res.setHeader('content-type','application/json');res.end(JSON.stringify(handle(JSON.parse(s))));}catch{res.statusCode=400;res.end('{}');}});

